use super::*;
#[derive(Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct PiSettings {
    pub lock_timeout_ms: u64,
    pub lock_poll_ms: u64,
    pub lock_max_hold_ms: u64,
    pub context_window: u64,
    pub max_tokens: u64,
    pub reasoning: bool,
    pub input: Vec<String>,
    pub cost: HashMap<String, f64>,
    pub aliases: HashMap<String, String>,
}
pub fn load() -> Result<PiSettings, String> {
    let mut value: Value = serde_json::from_str(include_str!("pi-default.json"))
        .map_err(|_| "ProviderConfigInvalid")?;
    if let Ok(path) = std::env::var("POLARIS_PROVIDER_CONFIG") {
        let patch: Value = serde_json::from_slice(&fs::read(path).map_err(|_| "ProviderConfigReadFailed")?)
            .map_err(|_| "ProviderConfigInvalid")?;
        let patch = patch.as_object().ok_or("ProviderConfigInvalid")?;
        let target = value.as_object_mut().ok_or("ProviderConfigInvalid")?;
        target.extend(patch.clone());
    }
    let settings: PiSettings = serde_json::from_value(value).map_err(|_| "ProviderConfigInvalid")?;
    if [settings.lock_max_hold_ms, settings.lock_timeout_ms, settings.lock_poll_ms]
        .iter().any(|v| *v == 0 || *v > 9007199254740991) || settings.context_window == 0
        || settings.max_tokens == 0 || settings.max_tokens > settings.context_window
        || settings.input.is_empty() || settings.input.iter().any(|s| s != "text" && s != "image")
        || ["input", "output", "cacheRead", "cacheWrite"].iter()
            .any(|k| settings.cost.get(*k).is_none_or(|v| !v.is_finite() || *v < 0.0)) {
        return Err("ProviderConfigInvalid".into());
    }
    Ok(settings)
}
use super::*;
#[cfg_attr(feature = "desktop", tauri::command(async))]
pub fn provider_switch(id: String) -> Result<String, String> {
    let store = STORE.read().clone();
    let views = build_views(&store);
    let v = views
        .iter()
        .find(|v| v.id == id)
        .ok_or_else(|| format!("供应商不存在: {id}"))?;

    if pi_translate::is_pi() {
        {
            let _mutation = PROVIDER_MUTATION.lock();
            STORE.write().current_id = id.clone();
            selection::changed();
        }
        persist_checked()?;
        crate::chat::backend::selected().map_err(|_| "AgentBackendUnavailable")?
            .provider_apply(&id).map_err(|e| e.to_string())?;
        return Ok(id);
    }
    // Legacy process env/settings mutations still serialize independently.
    static LEGACY_SWITCH: Lazy<parking_lot::Mutex<()>> = Lazy::new(|| parking_lot::Mutex::new(()));
    let _legacy = LEGACY_SWITCH.lock();
    let cfg = cfg_for_view(v, store.route_local)?;
    // 联动才碰全局 settings.json; 隔离只走进程 env, 外部 CLI 原封不动 ——
    // 但顺手做一次残留体检: 全局若还躺着我们(旧版/联动时代)写的受管键, 先清掉,
    // 用户不用重启 Polaris 外部 CLI 就立即恢复干净。
    if store.link_global {
        apply_settings_config(&cfg)?;
    } else {
        purge_global_residue(&views, &store);
    }
    apply_process_env(&cfg);

    {
        let _mutation = PROVIDER_MUTATION.lock();
        STORE.write().current_id = id.clone();
        selection::changed();
    }
    persist();
    Ok(id)
}

#[cfg_attr(feature = "desktop", tauri::command(async))]
pub fn provider_set_link_mode(link: bool) -> Result<bool, String> {
    if pi_translate::is_pi() { return Err("ProviderLinkModeUnsupported: Pi 后端不使用 Claude 联动模式".into()); }
    STORE.write().link_global = link;
    persist();

    let store = STORE.read().clone();
    let views = build_views(&store);
    let cur = views.iter().find(|v| v.id == store.current_id);
    if link {
        // 开联动: 当前供应商立刻写入全局, 终端 CLI 即刻跟上。
        if let Some(v) = cur {
            if let Ok(cfg) = cfg_for_view(v, store.route_local) {
                apply_settings_config(&cfg)?;
                apply_process_env(&cfg);
            }
        }
    } else {
        // 关联动(转隔离): 全局退回官方(只清我们的受管键, 其余原样保留),
        // Polaris 自身改用进程 env 维持当前选择 —— 终端立刻恢复干净。
        apply_settings_config(&json!({ "env": {} }))?;
        if let Some(v) = cur {
            if let Ok(cfg) = cfg_for_view(v, store.route_local) {
                apply_process_env(&cfg);
            }
        }
    }
    Ok(link)
}

/// 本地路由总开关(cc-switch 式代理模式)。开 = 当前及后续切换的 Anthropic 兼容供应商
/// 统一改走 127.0.0.1 本地路由透传(热切换: 改 key 即刻生效); 关 = 回到直连。
/// 切换开关立即对「当前供应商」重新生效, 联动模式下全局 settings.json 同步校正。
#[cfg_attr(feature = "desktop", tauri::command(async))]
pub fn provider_set_route_mode(route: bool) -> Result<bool, String> {
    if pi_translate::is_pi() { return Err("ProviderRouteModeUnsupported: Pi 直接连接上游".into()); }
    STORE.write().route_local = route;
    persist();

    let store = STORE.read().clone();
    let views = build_views(&store);
    if let Some(v) = views.iter().find(|v| v.id == store.current_id) {
        if let Ok(cfg) = cfg_for_view(v, store.route_local) {
            if store.link_global {
                apply_settings_config(&cfg)?;
            }
            apply_process_env(&cfg);
        }
    }
    Ok(route)
}

#[cfg_attr(feature = "desktop", tauri::command(async))]
pub fn provider_save(input: ProviderInput) -> Result<String, String> {
    let token_field = input
        .token_field
        .clone()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| DEFAULT_TOKEN_FIELD.to_string());

    // settings_config 兜底为 {env:{}}
    let cfg = if input.settings_config.is_object() {
        input.settings_config.clone()
    } else {
        json!({ "env": {} })
    };

    let id = input
        .id
        .clone()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| format!("custom-{}", now_ms()));

    // 掩码回填:provider_list 出口已把密钥打成 `••••••••尾4`, 而这里是**整条覆盖写** ——
    // 用户只改了个模型名就点保存时, 回传的正是那串圆点, 不还原就等于把 key 抹成一串没用的
    // 圆点(拿去打上游必 401)。清空 key 走的是「删掉该 env 字段」那条路, 不受影响。
    // A masked value means "keep current credential", not "write this old
    // snapshot back". Login/refresh may have rotated it before we get the lock.
    let preserve_key = cfg_env_str(&cfg, &token_field).contains(MASK_BULLET);
    let mut cfg = unmask_secrets(cfg, &id, &token_field);
    if preserve_key && shared_path().is_some() {
        if let Some(env) = cfg.get_mut("env").and_then(Value::as_object_mut) {
            env.remove(&token_field);
            env.remove(DEFAULT_TOKEN_FIELD);
            env.remove(API_KEY_FIELD);
        }
    }

    // Pi 支持的协议名在具名映射表内；未知协议报错，不能静默降为 Anthropic。
    let protocol = match input.protocol.as_deref().map(str::trim) {
        None | Some("") => String::new(),
        Some(p) if pi_translate::PROTOCOL_APIS.iter().any(|(name, _)| *name == p) => p.into(),
        _ => return Err("ProviderProtocolUnsupported".into()),
    };

    let clear_key = !preserve_key && cfg_env_str(&cfg, &token_field).is_empty()
        && credential_file::read(pi_translate::credential_id(&id))?
            .is_some_and(|c| c["type"] == "api_key");
    let item = StoredProvider {
        id: id.clone(),
        name: input.name.trim().to_string(),
        note: input.note.trim().to_string(),
        website_url: normalize_url(&input.website_url),
        token_field,
        protocol,
        settings_config: cfg,
    };

    let mutation = PROVIDER_MUTATION.lock();
    let mut store = STORE.write();
    if let Some(existing) = store.items.iter_mut().find(|i| i.id == id) {
        *existing = item;
    } else {
        store.items.push(item);
    }
    selection::changed();
    drop(store);
    drop(mutation);
    persist_without(clear_key.then_some(id.as_str()))?;
    Ok(id)
}

#[cfg_attr(feature = "desktop", tauri::command(async))]
pub fn provider_delete(id: String) -> Result<(), String> {
    let mutation = PROVIDER_MUTATION.lock();
    let mut store = STORE.write();
    store.items.retain(|i| i.id != id);
    if store.current_id == id {
        store.current_id = "claude-official".to_string();
    }
    selection::changed();
    drop(store);
    drop(mutation);
    persist_without(Some(&id))?;
    Ok(())
}

use super::{protocol::Command, supervisor, translate::Translator};
use super::super::{config::Agentd, stream::Mailbox, BackendStatus};
use std::{sync::{Arc, mpsc}, time::{Duration, Instant}};
use parking_lot::Mutex;
use serde_json::Value;
pub type Reply = mpsc::SyncSender<Result<Value, String>>;
pub enum Control {
    Request(Command, Reply),
    Register { session: String, req: String, translator: Translator, stream: Arc<Mailbox>, timeout: Duration, reservation: (Arc<Mutex<std::collections::HashSet<String>>>, String), reply: Reply },
    Cancel(String, Reply),
    Input { req: String, text: String, follow_up: bool, reply: Reply },
    Bind(String, String, Reply),
    Fail(String, String),
    Stop,
    #[cfg(test)]
    TestExit(bool),
    #[cfg(test)]
    TestClose,
    #[cfg(test)]
    TestAgeIdle(Reply),
    #[cfg(test)]
    TestWaitPings(u32, Reply),
}
pub struct Client {
    pub config: Agentd,
    tx: tokio::sync::mpsc::Sender<Control>,
    pub status: Arc<Mutex<BackendStatus>>,
    pub active: Arc<Mutex<std::collections::HashMap<String, String>>>,
}
impl Client {
    pub fn new(config: Agentd) -> anyhow::Result<Arc<Self>> {
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
        let (tx, rx) = tokio::sync::mpsc::channel(config.channel_capacity);
        let client = Arc::new(Self { config: config.clone(), tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))), active: Arc::new(Mutex::new(Default::default())) });
        let status = client.status.clone();
        let active = client.active.clone();
        std::thread::Builder::new().name("agentd-supervisor".into()).spawn(move || {
            runtime.block_on(supervisor::run(config, rx, status, active));
        })?;
        Ok(client)
    }
    pub fn send(&self, mut command: Control) -> anyhow::Result<()> {
        let deadline = Instant::now() + Duration::from_millis(self.config.request_timeout_ms);
        loop {
            match self.tx.try_send(command) {
                Ok(()) => return Ok(()),
                Err(tokio::sync::mpsc::error::TrySendError::Full(c)) => command = c,
                Err(_) => anyhow::bail!("AgentdSupervisorStopped"),
            }
            anyhow::ensure!(Instant::now() < deadline, "AgentdControlTimeout");
            std::thread::sleep(Duration::from_millis(self.config.control_poll_ms));
        }
    }
    pub fn call(&self, command: Command) -> anyhow::Result<Value> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Request(command, tx))?;
        self.wait(rx)
    }
    pub fn wait(&self, rx: mpsc::Receiver<Result<Value, String>>) -> anyhow::Result<Value> {
        // Budget queue/serialization separately from the actor's request deadline,
        // so its specific write/response error wins over the caller's fallback.
        let timeout = self.config.request_timeout_ms.saturating_mul(2)
            .saturating_add(self.config.supervisor_tick_ms.saturating_mul(2));
        rx.recv_timeout(Duration::from_millis(timeout)).map_err(|error| {
            anyhow::anyhow!(match error {
                mpsc::RecvTimeoutError::Disconnected => super::routes::SUPERVISOR_EXITED,
                mpsc::RecvTimeoutError::Timeout => "AgentdRequestTimeout",
            })
        })?.map_err(anyhow::Error::msg)
    }
    pub fn cancel(&self, req: &str) -> anyhow::Result<()> {
        let (tx, rx) = mpsc::sync_channel(1);
        self.send(Control::Cancel(req.into(), tx))?;
        self.wait(rx).map(|_| ())
    }
    pub fn stop(&self) { let _ = self.send(Control::Stop); }
}
impl Drop for Client { fn drop(&mut self) { let _ = self.tx.try_send(Control::Stop); } }

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reply_disconnect_and_timeout_have_distinct_errors() -> anyhow::Result<()> {
        let mut config = super::super::tests::config();
        config.request_timeout_ms = 1;
        config.supervisor_tick_ms = 1;
        let (tx, _control) = tokio::sync::mpsc::channel(1);
        let client = Client { config, tx,
            status: Arc::new(Mutex::new(BackendStatus::new("pi"))),
            active: Arc::new(Mutex::new(Default::default())) };
        // A stale actor failure must not mask why recv_timeout returned.
        client.status.lock().last_error = Some("AgentdRestarting".into());
        let (reply, rx) = mpsc::sync_channel(1);
        drop(reply);
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected exit"))?;
        assert_eq!(error.to_string(), super::super::routes::SUPERVISOR_EXITED);
        let (_reply, rx) = mpsc::sync_channel(1);
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected timeout"))?;
        assert_eq!(error.to_string(), "AgentdRequestTimeout");
        let (reply, rx) = mpsc::sync_channel(1);
        reply.send(Err("AgentdWriterBackpressure".into()))?;
        let error = client.wait(rx).err().ok_or_else(|| anyhow::anyhow!("expected actor error"))?;
        assert_eq!(error.to_string(), "AgentdWriterBackpressure");
        Ok(())
    }
}
