use super::*;
use super::pi_config::PiSettings;

/// Legacy protocol names describe wire formats, not model vendors. Pi 1.0.4
/// API names are verified against pi-ai/dist/api/*.d.ts and models.md.
pub const PROTOCOL_APIS: &[(&str, &str)] = &[
