export class Models {
  private constructor(
    public runtime: ModelRuntime,
    readonly credentials: CredentialStore,
    readonly redactor: Redactor,
    public builtinCatalog: ReturnType<Models["list"]>,
  ) {}

  static async create(config: Config, credentials: CredentialStore, redactor: Redactor): Promise<Models> {
    for (const info of await credentials.list()) {
      const credential = await credentials.read(info.providerId);
      if (credential?.type === "api_key" && credential.key) redactor.add(credential.key);
      if (credential?.type === "oauth") { redactor.add(credential.access); redactor.add(credential.refresh); }
    }
    const { runtime, catalog } = await Models.build(config, credentials);
    return new Models(runtime, credentials, redactor, catalog);
  }

  private static async build(config: Config, credentials: CredentialStore) {
    const runtime = await ModelRuntime.create({ credentials, modelsPath: null, allowModelNetwork: false });
    const builtinProviders = new Set(runtime.getModels().map((m) => m.provider));
    for (const { id, ...provider } of config.providers) runtime.registerProvider(id, provider);
    if (runtime.getError()) throw new DaemonError("INVALID_PROVIDER", "Provider configuration is invalid");
    const catalog = runtime.getModels().filter((m) => builtinProviders.has(m.provider)).map(({ provider, id, name, api, baseUrl, input, cost, reasoning, contextWindow, maxTokens }) => ({
      provider, id, name, api, baseUrl, input, cost, reasoning, contextWindow, maxTokens,
    }));
    return { runtime, catalog };
  }

  async apply(config: Config, keys: Credentials = {}): Promise<void> {
    for (const key of Object.values(keys)) if (key) this.redactor.add(key);
    const candidate = await Models.build(config, this.credentials);
    for (const [provider, key] of Object.entries(keys)) {
      if (key === null) await this.credentials.delete(provider);
      else await this.credentials.modify(provider, async () => ({ type: "api_key", key }));
    }
    this.runtime = candidate.runtime;
    this.builtinCatalog = candidate.catalog;
  }

  list() {
    return this.runtime.getModels().map(({ provider, id, name, api, baseUrl, input, cost, reasoning, contextWindow, maxTokens }) => ({
      provider, id, name, api, baseUrl, input, cost, reasoning, contextWindow, maxTokens,
    }));
  }
}
import { mkdirSync, openSync, closeSync, writeFileSync, fsyncSync, renameSync, rmSync } from "node:fs";
import { join } from "node:path";
import { createHash, randomUUID } from "node:crypto";
import type { AssistantMessage } from "@earendil-works/pi-ai";
import type { ModelRuntime } from "@earendil-works/pi-coding-agent";
import { Value } from "typebox/value";
import { UsageSchema } from "../protocol/events.ts";

/** One atomic record per provider request; no prompts, headers, or credentials. */
export function recordUsage(directory: string, sessionId: string, turnId: string, ordinal: number,
  message: AssistantMessage, runtime: Pick<ModelRuntime, "getModel">): void {
  if (!directory) return;
  if (!Value.Check(UsageSchema, message.usage) || !Number.isFinite(message.timestamp)) throw new Error("UsageInvalid");
  const cost = runtime.getModel(message.provider, message.model)?.cost;
  const rates = cost ? [cost.input, cost.output, cost.cacheRead, cost.cacheWrite] : [];
  // A zero-cost request can still use a priced model. Missing/all-zero definitions are unpriced.
  const priceAvailable = rates.every((rate) => Number.isFinite(rate) && rate >= 0)
    && rates.some((rate) => rate > 0);
  const date = new Date(message.timestamp).toISOString().slice(0, 10);
  const requestId = message.responseId || `${sessionId}:${turnId}:${ordinal}`;
  const id = createHash("sha256").update(JSON.stringify([date, message.provider, requestId])).digest("hex");
  const dir = join(directory, date);
  mkdirSync(dir, { recursive: true });
  const path = join(dir, `${id}.json`);
  const temp = `${path}.${randomUUID()}.tmp`;
  const row = { version: 1, sessionId, turnId, requestId, provider: message.provider,
    model: message.model, timestamp: message.timestamp, date, usage: message.usage, priceAvailable,
    // Only Anthropic's native message id can identify a copied legacy CLI row.
    legacyMessageId: message.api === "anthropic-messages" ? message.responseId : undefined };
  try {
    const fd = openSync(temp, "wx", 0o600);
    try { writeFileSync(fd, JSON.stringify(row)); fsyncSync(fd); } finally { closeSync(fd); }
    renameSync(temp, path);
  } finally { rmSync(temp, { force: true }); }
}
