[package]
name = "polaris-collab"
version = "0.1.0"
edition = "2021"
publish = false

[dependencies]
polaris-kernel = { path = "../polaris-kernel" }
polaris-runtime = { path = "../polaris-runtime" }
# 版本与主 crate 逐条对齐(同 workspace 共享编译产物,零增量)
serde = { version = "1", features = ["derive"] }
serde_json = "1"
anyhow = "1"
once_cell = "1"
parking_lot = "0.12"
regex = "1"
directories = "5"
walkdir = "2"
