/// 这个云端账号在本机**已经有成员资格**了吗。纯本地读,不联网 ——
/// 设备网的对账循环每拍都要问一次「我进得了自己这台机器的门吗」,不能为此打一趟公网。
pub fn is_member(uid: &str) -> bool {
    let uid = uid.trim();
    if uid.is_empty() {
        return false;
    }
    let Ok(conn) = open_db() else { return false };
    conn.query_row(
        "SELECT 1 FROM users WHERE uid=?1 AND disabled=0 LIMIT 1",
        params![uid],
        |_| Ok(()),
    )
    .optional()
    .map(|x| x.is_some())
    .unwrap_or(false)
}

