//! Docker(server) 外壳的「宿主句柄」shim。
//!
//! 桌面版的引擎模块函数签名里写的是 `app: AppHandle`（tauri），函数体里调用
//! `app.emit("topic", payload)`、`app.clone()`、`app.path().resource_dir()`。
//! server 构建下用 `#[cfg(not(feature = "desktop"))] use crate::host::AppHandle;`
//! 把这些调用原样接到这里——**因此 17 个引擎模块的函数体一行都不用改**，
//! 桌面 / Docker 共用同一份源码（满足「Windows 更新后 Docker 快速更新」）。

use serde::Serialize;
use std::path::PathBuf;
use tokio::sync::broadcast;

/// 一条推给浏览器前端的事件：topic（对应桌面 `listen(topic)`）+ JSON payload。
#[derive(Clone, Debug)]
pub struct Event {
    pub topic: String,
    pub payload: serde_json::Value,
    /// 事件受众:None=广播给所有连接;Some(username)=只投递给该用户(owner 全收)。
    /// 多人协作(/ws 按用户过滤)的最小侵入实现——引擎模块无感,定向事件走 emit_to。
    pub audience: Option<String>,
    /// 预序列化的 WS 帧(`{"topic":…,"payload":…}` 的最终 JSON 串):emit 时序列化**一次**,
    /// N 条 WS 连接共享同一份 Arc,ws_loop 不再对每条连接各跑一遍 serde(热路径主要收益)。
    /// payload 仍保留 Value 形态,供 hosting 的 UI 桥(tauri emit)与调试用。
    pub frame: std::sync::Arc<str>,
}

impl Event {
    /// 构造事件并预序列化一帧。Value 序列化不会失败;兜底帧仅防御性存在。
    pub fn new(topic: String, payload: serde_json::Value, audience: Option<String>) -> Self {
        // 字段序对齐旧实现:旧 `json!({"topic","payload"})` 走 serde_json 的 BTreeMap,
        // 输出是字典序 `payload` 在前;serde 结构体按声明序,故这里也把 payload 放前面,
        // 让新旧帧逐字节一致(防按帧字节签名/哈希的客户端因键序变化失配)。
        #[derive(Serialize)]
        struct Frame<'a> {
            payload: &'a serde_json::Value,
            topic: &'a str,
        }
        let frame: std::sync::Arc<str> = serde_json::to_string(&Frame {
            payload: &payload,
            topic: &topic,
        })
        .unwrap_or_else(|_| "{\"payload\":null,\"topic\":\"\"}".to_string())
        .into();
        Self {
            topic,
            payload,
            audience,
            frame,
        }
    }
}

/// server 模式下替代 `tauri::AppHandle` 的轻量句柄（Clone + Send + Sync）。
/// 内部持有一个广播发送端：所有 emit 都广播给全部 WS 订阅者，前端按 reqId/runId 自行过滤。
#[derive(Clone)]
pub struct AppHandle {
    tx: broadcast::Sender<Event>,
}

impl AppHandle {
    pub fn new(tx: broadcast::Sender<Event>) -> Self {
        Self { tx }
    }

    /// 新建一个订阅端（每个 WS 连接一个）。
    pub fn subscribe(&self) -> broadcast::Receiver<Event> {
        self.tx.subscribe()
    }

    /// 克隆底层发送端（极少用到；emit 已覆盖绝大多数场景）。
    pub fn sender(&self) -> broadcast::Sender<Event> {
        self.tx.clone()
    }

    /// 对应 `tauri::Emitter::emit`：序列化 payload → 广播。
    /// 无 WS 订阅者时 `send` 返回 Err（频道里暂时没人），按桌面 `let _ = emit` 的语义忽略。
    pub fn emit<S: Serialize>(&self, topic: &str, payload: S) -> Result<(), serde_json::Error> {
        let value = serde_json::to_value(payload)?;
        let _ = self.tx.send(Event::new(topic.to_string(), value, None));
        Ok(())
    }

    /// emit 的 Value 直通版:payload 已是 Value 时跳过 `to_value` 的整树重建
    /// (泛型 emit 对 Value 入参也会经 Serializer 深拷贝一遍)。hosting 的对话流桥
    /// (tauri 字符串 → Value → bus)这类热路径用它。
/// 受控远程执行端点(B 方案)。刻意**不**并进 /api/invoke:
/// invoke 的闸是「命令在不在分发表」,exec 的闸是「总开关+模式+白名单」,
/// 两套语义混一个入口迟早互相漏。闸门顺序与理由见 exec.rs 头注释。
async fn exec_ep(
    State(state): State<ApiState>,
    headers: HeaderMap,
    Json(req): Json<crate::exec::ExecRequest>,
) -> Response {
    let gate = OriginGate::closed();
    // 闸 2:fail-closed。没设访问口令且没强制登录 = 基础面免口令(合成 owner),
    // 那对 exec 就是**无鉴权 shell**。这里直接拒,且不提供开关绕过。
    // 注:这里刻意**不**走「内网免口令」(OriginGate::closed()),exec 必须拿到真凭据 ——
    // 内网免口令是为了让家用 NAS 用户能进对话/知识库,不是为了给局域网开一个无鉴权 shell。
    if effective_token(&state.auth_token).is_none() && !require_login_env() {
        crate::collab::db::audit(
            "anonymous",
            "exec.denied",
            &req.cmd,
            "开放模式(未设访问口令)",
        );
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"本机未设访问口令,远程执行已禁用。请给容器设 POLARIS_AUTH_TOKEN(或 POLARIS_REQUIRE_LOGIN=1)再用"})),
        )
            .into_response();
    }
    let Some(ctx) = app_ctx(&state, &headers, gate).await else {
        return (
            StatusCode::UNAUTHORIZED,
            Json(json!({"error":"未授权 (口令错误或会话失效)"})),
        )
            .into_response();
    };
    // 闸 3:**按设备**。会话上记着这条请求来自哪台设备,台账上那一排「远程执行:
    // 禁止/每次问/允许」在这里才真的生效。设备码进来的对端默认禁止 —— 拿到码不等于
    // 拿到一个 shell,那要机主在台账上单独点头。本机自己/全局口令不受此闸(device_id 为空)。
    let dev = crate::collab::http::bearer_of(&headers)
        .and_then(|t| crate::collab::auth::check_session_with_device(&t).ok())
        .map(|(_, d)| d)
        .unwrap_or_default();
    if let Err(e) = crate::collab::grants::exec_gate(&dev) {
        crate::collab::db::audit(&ctx.username, "exec.denied", &req.cmd, &e);
        return (StatusCode::FORBIDDEN, Json(json!({ "error": e }))).into_response();
    }
    // 角色闸只对**没有设备契约**的调用方生效:设备码进来的是 visitor,它的权限
    // 完全由上面那道契约闸说了算,再压一道 owner 角色等于把这条路彻底堵死。
    let by_grant = matches!(crate::collab::grants::get(&dev), Ok(Some(g)) if !g.revoked);
    if !by_grant && role_rank(&ctx.role) < 3 {
        crate::collab::db::audit(&ctx.username, "exec.denied", &req.cmd, "角色不足");
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"远程执行需要 owner 权限"})),
        )
            .into_response();
    }
    match crate::exec::run(&ctx.username, req).await {
        // 命令跑完即 200(哪怕退出码非 0)——那是命令的结果,不是接口的错误;
        // 调用方看 exit_code/ok 字段。只有闸门拒绝/启动失败才给非 2xx。
        Ok(r) => Json(r).into_response(),
        Err(e) => {
            // 闸门拒绝是 403(不是 500):调用方据此提示「让主机侧开开关/解锁 Shell」。
            let status = if e.contains("未开启远程执行")
                || e.contains("不在白名单")
                || e.contains("白名单模式")
                || e.contains("元字符")
                || e.contains("不能带路径")
            {
                StatusCode::FORBIDDEN
            } else if e.contains("缺少参数")
                || e.contains("工作目录不存在")
                || e.contains("启动失败")
            {
                StatusCode::BAD_REQUEST
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            (status, Json(json!({ "error": e }))).into_response()
        }
    }
}
