/bin/bash -lc "rg -n 'id: \"gpt\"|id: \"codex\"' src-tauri/crates/polaris-kernel/src/provider/store/presets.rs
python3 - <<'PY'
from pathlib import Path
import tempfile, shutil, subprocess
root=Path.cwd(); target=Path(tempfile.mkdtemp(prefix='p7-schema-baseline-'))
for name in ['src','test','config']: shutil.copytree(root/'agentd'/name,target/name)
for name in ['package.json','tsconfig.json']: shutil.copy2(root/'agentd'/name,target/name)
(target/'node_modules').symlink_to(root/'agentd/node_modules',target_is_directory=True)
for name in ['src/config/schema.ts','src/daemon.ts','src/models/runtime.ts','src/protocol/schema.ts']:
 (target/name).write_bytes(subprocess.check_output(['git','show','HEAD:agentd/'+name]))
code='''import {harness,providerConfig} from \"./test/helpers.ts\";
const h = await harness();
try {
 const model = h.daemon.models.builtinCatalog.find(m => m.provider === \"openai\" && m.id === \"gpt-6-astra\");
 if ("'!model?.cost.tiers) throw new Error("Missing tiered catalog model");
 const response = await h.request("config.apply", {config:{providers:[providerConfig(model)]}});
 console.log(JSON.stringify({provider:model.provider, model:model.id, response}));
} finally { await h.close(); }
'"'''
with open('/tmp/p7-original-schema-paths-final.log','w') as out:
 result=subprocess.run(['node','--import','tsx','--input-type=module','-e',code],cwd=target,stdout=out,stderr=subprocess.STDOUT)
 print('original schema reproduction exit',result.returncode)
shutil.rmtree(target)
PY"

